import React from 'react';
import './projects.css';
import Image1 from "../../assets/aadarsh.jpg";

import { Swiper, SwiperSlide } from "swiper/react";

import "swiper/css";
import "swiper/css/pagination";

import { Autoplay, Mousewheel, Pagination } from 'swiper/modules';

const Project = () => {
  return (
    <section className="projects section" id="projects">
      <span className="section-subtitle">
        Discover My Projects
      </span>
      <h2 className="section-title">Projects</h2>
      <Swiper
        direction={'vertical'}
        slidesPerView={1}
        spaceBetween={30}
        mousewheel={true}
        // autoplay={{
        //   delay: 2000,
        //   disableOnInteraction: false,
        // }}
        pagination={{
          clickable: true,
        }}
        modules={[Mousewheel, Autoplay, Pagination]}
        className="projects-container container"
      >
        <SwiperSlide className='project-content'>
          <img src={Image1} alt="sudeshna's img" className="project-img" />

          <div className='about-data'>
            <h2 className='project-title'>Experience</h2>
            <p className="about-description">Developer I create web pages with UI / UX user interface, I have yeares of experience and many cliernts are happy with the projects carried out.Developer I create web pages with UI / UX user interface, I have yeares of experience and many cliernts are happy with the projects carried out.</p>

            <a href="#" className="button button-flex">View
              <i class="uil uil-link"></i>
            </a>
          </div>
        </SwiperSlide>
        <SwiperSlide>
          <img src={Image1} alt="sudeshna's img" className="project-img" />

          <div className='about-data'>
            <h2 className='project-title'>Experience</h2>
            <p className="about-description">Developer I create web pages with UI / UX user interface, I have yeares of experience and many cliernts are happy with the projects carried out.Developer I create web pages with UI / UX user interface, I have yeares of experience and many cliernts are happy with the projects carried out.</p>

            <a href="#" className="button button-flex">View
              <i class="uil uil-link"></i>
            </a>
          </div>
        </SwiperSlide>
        <SwiperSlide>Slide 3</SwiperSlide>

      </Swiper>
    </section>
  );
};

export default Project;
